package io.knowledgebrain.activity;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import java.time.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_ACTIVITY_CLICKHOUSE",matches=".+")
class ActivityClickHouseIntegrationTest extends ActivityFixtures {
 ActivityClickHouse reader,writer;
 @BeforeEach void init()throws Exception{var origin=System.getenv("BRAIN_TEST_ACTIVITY_CLICKHOUSE");reader=new ActivityClickHouse(origin,"/activity-trust/ca.crt","/clickhouse-reader");writer=new ActivityClickHouse(origin,"/activity-trust/ca.crt","/clickhouse-projector");}
 @Test void verifiedTlsDuplicateReplaySpaceIsolationAndEqualTimeKeysetPaging(){var space=id();long time=Instant.parse("2026-11-01T05:30:00Z").toEpochMilli();var events=new ArrayList<ActivityEvent>();for(int i=0;i<ActivityEvent.TOPICS.size();i++){var k=List.copyOf(ActivityEvent.TOPICS.keySet()).get(i);var e=ActivityEvent.decode(ActivityEvent.TOPICS.get(k),wire(k,space,id(),id(),1,time));events.add(e);}writer.applyAll(events);writer.applyAll(events);var unrelated=ActivityEvent.decode(ActivityEvent.TOPICS.get("ROADMAP"),wire("ROADMAP",id()));writer.apply(unrelated);events.sort(Comparator.comparing((ActivityEvent e)->e.eventId().toString()).reversed());var params=ActivityQueryTest.params("from","2026-11-01","to","2026-11-01","timezone","America/New_York","limit","3");var q=ActivityQuery.parse(space,params);assertEquals(events.subList(0,4),reader.list(space,q));params.put("before",new String[]{q.cursor(events.get(2))});assertEquals(events.subList(3,7),reader.list(space,ActivityQuery.parse(space,params)));params.remove("before");params.put("kind",new String[]{"STUDY_SESSION"});assertEquals(1,reader.list(space,ActivityQuery.parse(space,params)).size());params.put("from",new String[]{"2026-11-02"});params.put("to",new String[]{"2026-11-02"});assertTrue(reader.list(space,ActivityQuery.parse(space,params)).isEmpty());assertThrows(IllegalStateException.class,()->reader.apply(unrelated));}
 @Test void fullHundredEntryPagePreservesMaximumEscapedPlanningDescriptions()throws Exception{var space=id();var events=new ArrayList<ActivityEvent>();for(int i=0;i<100;i++){var wire=wire("TASK",space);var env=io.knowledgebrain.contracts.planning.task.v1.TaskEventEnvelopeV1.parseFrom(wire);var payload=io.knowledgebrain.contracts.planning.task.v1.TaskChangedPayloadV1.parseFrom(env.getPayload()).toBuilder().setDescription("\"".repeat(32768)).build();events.add(ActivityEvent.decode(ActivityEvent.TOPICS.get("TASK"),env.toBuilder().setPayload(payload.toByteString()).build().toByteArray()));}writer.applyAll(events);var rows=reader.list(space,ActivityQuery.parse(space,ActivityQueryTest.params("kind","TASK","limit","100")));assertEquals(100,rows.size());assertTrue(rows.stream().allMatch(e->e.detail().equals("\"".repeat(32768))));}
}
